{
  "info": {
    "path": "/Volumes/EXTERNAL/自媒体/AI博主1000视频研究-20261007/指定5账号近两月-20261009/media/7672052824909401370.mp4",
    "source": "/Volumes/EXTERNAL/自媒体/AI博主1000视频研究-20261007/指定5账号近两月-20261009/media/7672052824909401370.mp4",
    "sourceKind": "local",
    "durationSec": 359.205,
    "width": 1440,
    "height": 2554,
    "fps": 60,
    "videoCodec": "hevc",
    "audioCodec": "aac",
    "hasAudio": true,
    "hasVideo": true,
    "bitrate": 1699684,
